/**
 * Client bundle test.
 *
 * Verifies the browser half ships as one generated module and that its plugin
 * entry contributes the external plugin section:
 *   1. client.js starts with the generated header and registers one bundle.
 *   2. The factory requires React and the client primitives, and returns the
 *      slots and locale injection plus apply.
 *   3. apply installs the zh and en dictionaries, the placement stylesheet and
 *      the section.
 *   4. The component renders nothing for every other detail page subject.
 *   5. The section renders loading, error, empty and populated states in the
 *      same row form the page uses for a bundle's components.
 *   6. A switch posts the requested runtime state and replaces its row from the
 *      returned snapshot, and a failed switch keeps the row and shows the
 *      message.
 *
 * The test runs without a DOM: the loader facade, React, the primitives and
 * fetch are stubs.
 */

import { strict as assert } from 'node:assert'
import { readFile } from 'node:fs/promises'

const bundleUrl = new URL('../client.js', import.meta.url)
const bundleSource = await readFile(bundleUrl, 'utf8')

const failures = []
let passed = 0

async function check(name, run, detail = '') {
  try {
    await run()
    passed++
    console.log(`  ok   ${name}`)
  } catch (error) {
    failures.push(name)
    const reason = error instanceof Error ? error.message : String(error)
    console.log(`  FAIL ${name}${detail ? ` [${detail}]` : ''}: ${reason}`)
  }
}

const section = (title) => console.log(`\n${title}`)

/** Minimal React stub: elements are plain objects and hooks keep their initial value. */
function createReactStub() {
  return {
    createElement(tag, props, ...children) {
      const merged = children.length === 0
        ? { ...props }
        : { ...props, children: children.length === 1 ? children[0] : children }
      return { tag, props: merged, children }
    },
    useState(initial) {
      return [typeof initial === 'function' ? initial() : initial, () => {}]
    },
    useEffect() {},
  }
}

/** A client primitive stub: an identifiable element that renders the children a call passes. */
function primitiveStub(tag) {
  return (props = {}) => {
    const { children, ...rest } = props
    const list = children === undefined ? [] : Array.isArray(children) ? children : [children]
    return { tag, props: rest, children: list }
  }
}

const primitives = {
  Button: primitiveStub('stub-button'),
  PluginArtworkDefault: primitiveStub('stub-artwork'),
  StateDot: primitiveStub('stub-state-dot'),
  Switch: primitiveStub('stub-switch'),
}

/** Visit every element in a rendered tree, including arrays of children. */
function walk(node, visit) {
  if (node === null || typeof node !== 'object') return
  if (Array.isArray(node)) {
    for (const child of node) walk(child, visit)
    return
  }
  visit(node)
  for (const child of node.children) walk(child, visit)
}

/** Collect the text children of every element in a rendered tree. */
function textsOf(node) {
  const texts = []
  walk(node, (element) => {
    for (const child of element.children) if (typeof child === 'string') texts.push(child)
  })
  return texts
}

/** Every element of a rendered tree, in render order. */
function elementsOf(tree) {
  const elements = []
  walk(tree, (element) => elements.push(element))
  return elements
}

/** Expand the function components a section renders, so the stub primitives appear as elements. */
function expandComponents(node) {
  if (node === null || typeof node !== 'object') return node
  if (Array.isArray(node)) return node.map(expandComponents)
  if (typeof node.tag === 'function') return expandComponents(node.tag(node.props))
  return { ...node, children: node.children.map(expandComponents) }
}

/** Let a pending promise chain settle. */
const settle = () => new Promise((resolve) => setTimeout(resolve, 0))

const loadCalls = []
globalThis.window = { __ModuleLoader__: { load(registration) { loadCalls.push(registration) } } }
const react = createReactStub()
const required = []
const requireStub = (specifier) => {
  required.push(specifier)
  if (specifier === 'react') return react
  if (specifier === '@deepseek-ai/dsh-client-ui-primitives') return primitives
  throw new Error(`unexpected require: ${specifier}`)
}

await import(bundleUrl.href)

async function main() {
  section('1. Generated bundle')
  await check('client.js starts with the generated header', () => {
    assert.ok(bundleSource.startsWith('// Generated by scripts/build-client.mjs. Do not edit by hand.\n'))
    assert.ok(bundleSource.endsWith('\n'), 'file ends with a newline')
  })
  await check('client.js registers one dsh-mloader bundle', () => {
    assert.equal(loadCalls.length, 1)
    assert.equal(loadCalls[0].id, 'dsh-mloader')
    assert.equal(typeof loadCalls[0].factory, 'function')
    assert.equal((bundleSource.match(/__ModuleLoader__\.load\(/g) ?? []).length, 1)
  })

  const pluginEntry = loadCalls[0].factory(requireStub)

  await check('the factory requires React and the client primitives', () => {
    assert.deepEqual(required, ['react', '@deepseek-ai/dsh-client-ui-primitives'])
    const requests = [...bundleSource.matchAll(/require\(([^)]*)\)/g)].map((match) => match[1])
    assert.deepEqual(requests, ['"react"', '"@deepseek-ai/dsh-client-ui-primitives"'])
  })
  await check('the bundle exports the slots and locale injection plus apply', () => {
    assert.deepEqual(pluginEntry.inject, ['slots', 'locale'])
    assert.equal(typeof pluginEntry.apply, 'function')
  })

  section('2. apply installs the dictionaries, the placement rule and the section')
  const capture = { injections: [], locales: [], registration: null }
  const ctx = {
    slots: {
      inject(name, callback) { capture.injections.push(name); return callback() },
      register(options, Component) { capture.registration = { options, Component }; return () => {} },
    },
    locale: {
      register(namespace, dictionaries) { capture.locales.push({ namespace, dictionaries }); return () => {} },
      bind() { return (key) => key },
    },
    effect(setup) { return setup() },
  }
  pluginEntry.apply(ctx)

  await check('apply injects the plugins.detail.section slot once', () => {
    assert.deepEqual(capture.injections, ['plugins.detail.section'])
  })
  await check('the registration carries the expected identity', () => {
    assert.notEqual(capture.registration, null)
    assert.equal(capture.registration.options.name, 'plugins.detail.section')
    assert.equal(capture.registration.options.id, 'mloader-external-plugins')
    assert.equal(capture.registration.options.order, 10)
    assert.equal(capture.registration.options.locale, 'mloader')
  })
  await check('apply registers the mloader zh and en dictionaries', () => {
    assert.equal(capture.locales.length, 1)
    assert.equal(capture.locales[0].namespace, 'mloader')
    const { zh, en } = capture.locales[0].dictionaries
    assert.ok(zh && en)
    assert.deepEqual(Object.keys(zh).sort(), Object.keys(en).sort())
  })
  await check('the zh dictionary covers the required copy', () => {
    const zh = capture.locales[0].dictionaries.zh
    const values = Object.values(zh)
    for (const expected of ['外部插件', '没有外部插件', '重试']) assert.ok(values.includes(expected), expected)
    for (const fragment of ['加载中', '加载失败']) {
      assert.ok(values.some((value) => value.includes(fragment)), fragment)
    }
    for (const state of ['运行中', '已关闭', '异常', '未运行', '已移除']) assert.ok(values.includes(state), state)
    for (const fragment of ['共 {count} 个', '{count} 运行中', '{count} 已停用', '{count} 异常']) {
      assert.ok(values.includes(fragment), fragment)
    }
    assert.ok(values.some((value) => value.includes('{name}')), 'switch aria-label')
  })
  await check('apply installs the placement stylesheet and removes it with its effect', () => {
    const appended = []
    const removed = []
    const cleanups = []
    const previousDocument = globalThis.document
    globalThis.document = {
      getElementById() { return null },
      createElement(tag) { return { tag, id: '', textContent: '', remove() { removed.push(true) } } },
      head: { append(node) { appended.push(node) } },
    }
    try {
      pluginEntry.apply({
        slots: {
          inject(name, callback) { return callback() },
          register() { return () => {} },
        },
        locale: {
          register() { return () => {} },
          bind() { return (key) => key },
        },
        effect(setup) { const cleanup = setup(); cleanups.push(cleanup); return cleanup },
      })
    } finally {
      globalThis.document = previousDocument
    }
    assert.equal(appended.length, 1)
    assert.equal(appended[0].tag, 'style')
    assert.equal(appended[0].id, 'dsh-mloader-client-style')
    assert.ok(appended[0].textContent.includes('[data-plugin-detail="dsh-mloader"]'))
    for (const cleanup of cleanups) if (typeof cleanup === 'function') cleanup()
    assert.equal(removed.length, 1)
  })
  await check('apply returns early without the client services', () => {
    pluginEntry.apply({})
    pluginEntry.apply({ slots: ctx.slots })
    pluginEntry.apply({ locale: ctx.locale })
  })

  section('3. The section renders only for the dsh-mloader bundle')
  const Component = capture.registration.Component
  const match = { kind: 'bundle', pkg: { name: 'dsh-mloader' } }
  await check('another bundle renders nothing', () => {
    assert.equal(Component({ subject: { kind: 'bundle', pkg: { name: 'other-bundle' } } }), null)
  })
  await check('a row, an official item or a missing subject renders nothing', () => {
    assert.equal(Component({ subject: { kind: 'row', pkg: { name: 'dsh-mloader' } } }), null)
    assert.equal(Component({ subject: { kind: 'item', id: 'dsh-mloader' } }), null)
    assert.equal(Component({}), null)
  })
  await check('the dsh-mloader bundle renders the section head and the loading state', () => {
    const tree = Component({ subject: match })
    assert.notEqual(tree, null)
    assert.equal(typeof tree.tag, 'function')
    const body = tree.tag(tree.props)
    assert.notEqual(body, null)
    assert.equal(body.props['data-mloader'], 'external-plugins')
    assert.equal(body.props.style.order, 1, 'the section claims its place under the component rows')
    const texts = textsOf(body)
    assert.ok(texts.includes('title'))
    assert.ok(texts.includes('loading'))
  })

  section('4. Rows and runtime switches')
  /** Render the section body with a controlled list and record every state update. */
  function renderWithPlugins(plugins, status = 'ready', error = '') {
    const previousUseState = react.useState
    const updates = []
    let hook = 0
    react.useState = (initial) => {
      hook += 1
      const index = hook
      const setter = (next) => { updates.push({ index, next }) }
      if (index === 1) return [plugins, setter]
      if (index === 2) return [status, setter]
      if (index === 3) return [error, setter]
      return [typeof initial === 'function' ? initial() : initial, setter]
    }
    try {
      const wrapper = Component({ subject: match })
      const body = expandComponents(wrapper.tag(wrapper.props))
      return { body, elements: elementsOf(body), updates }
    } finally {
      react.useState = previousUseState
    }
  }

  /** Run the section's single switch against a stub host and settle its request. */
  async function toggleWith(plugin, enabled, response) {
    const { elements, updates } = renderWithPlugins([plugin])
    const switches = elements.filter((element) => element.tag === 'stub-switch')
    assert.equal(switches.length, 1, 'one switch per row')
    const requests = []
    const previousFetch = globalThis.fetch
    globalThis.fetch = async (url, init) => {
      requests.push({ url, init })
      return response
    }
    try {
      switches[0].props.onChange(enabled)
      await settle()
    } finally {
      globalThis.fetch = previousFetch
    }
    return { switch: switches[0], updates, requests }
  }

  const applied = {
    id: 'py-hello',
    name: 'Python Hello',
    version: '0.1.0',
    backend: 'python',
    state: 'applied',
    tools: ['hello_add', 'hello_mloader'],
    events: [],
    registrations: 2,
  }

  await check('one row shows artwork, identity, metadata, state and an accessible switch', () => {
    const { body, elements } = renderWithPlugins([applied])
    const switches = elements.filter((element) => element.tag === 'stub-switch')
    assert.equal(switches.length, 1)
    assert.equal(switches[0].props.checked, true)
    assert.equal(switches[0].props.disabled, false)
    assert.equal(typeof switches[0].props.label, 'string')
    assert.ok(switches[0].props.label.length > 0)
    const dots = elements.filter((element) => element.tag === 'stub-state-dot')
    assert.deepEqual(dots.map((element) => element.props.state), ['done'])
    assert.equal(elements.filter((element) => element.tag === 'stub-artwork').length, 1)
    const texts = textsOf(body)
    assert.ok(texts.includes('py-hello'))
    assert.ok(texts.includes('Python Hello'))
    assert.ok(texts.includes('stateApplied'))
    assert.ok(texts.some((text) => text.includes('python') && text.includes('toolsCount')))
    assert.ok(texts.some((text) => text.includes('partsCountTotal')))
  })
  await check('an empty plugin list shows the empty state', () => {
    const { body } = renderWithPlugins([])
    assert.ok(textsOf(body).includes('empty'))
  })
  await check('a failed load shows the error state and the retry control', () => {
    const { elements } = renderWithPlugins([], 'error', 'boom')
    const texts = textsOf({ tag: 'root', props: {}, children: elements })
    assert.ok(texts.some((text) => text.includes('loadFailed') && text.includes('boom')))
    const retry = elements.filter((element) => element.tag === 'stub-button')
    assert.equal(retry.length, 1)
    assert.ok(textsOf(retry[0]).includes('retry'))
  })
  await check('a failed plugin shows the error dot and the host message', () => {
    const failed = { ...applied, state: 'failed', error: 'process exited' }
    const { body, elements } = renderWithPlugins([failed])
    const dots = elements.filter((element) => element.tag === 'stub-state-dot')
    assert.deepEqual(dots.map((element) => element.props.state), ['error'])
    const texts = textsOf(body)
    assert.ok(texts.includes('stateFailed'))
    assert.ok(texts.includes('process exited'))
  })
  await check('a switch on an applied plugin posts enabled false and replaces its row', async () => {
    const { updates, requests } = await toggleWith(applied, false, {
      ok: true,
      status: 200,
      json: async () => ({ plugin: { ...applied, state: 'disabled' } }),
    })
    assert.equal(requests.length, 1)
    assert.equal(requests[0].url, '/mloader/plugins/toggle')
    assert.equal(requests[0].init.method, 'POST')
    assert.equal(requests[0].init.credentials, 'same-origin')
    assert.deepEqual(JSON.parse(requests[0].init.body), { id: 'py-hello', enabled: false })
    const replacement = updates.find((update) => update.index === 1 && typeof update.next === 'function')
    assert.ok(replacement, 'row replacement')
    const rows = replacement.next([applied])
    assert.equal(rows.length, 1)
    assert.equal(rows[0].state, 'disabled')
    const pending = updates.filter((update) => update.index === 4)
    assert.deepEqual(pending.map((update) => update.next), ['py-hello', ''])
  })
  await check('a switch on a disabled plugin posts enabled true', async () => {
    const disabled = { ...applied, state: 'disabled' }
    const { updates, requests } = await toggleWith(disabled, true, {
      ok: true,
      status: 200,
      json: async () => ({ plugin: { ...applied, state: 'applied' } }),
    })
    assert.deepEqual(JSON.parse(requests[0].init.body), { id: 'py-hello', enabled: true })
    const replacement = updates.find((update) => update.index === 1 && typeof update.next === 'function')
    assert.equal(replacement.next([disabled])[0].state, 'applied')
  })
  await check('a failed switch keeps the row and surfaces the message', async () => {
    const { updates, requests } = await toggleWith(applied, false, {
      ok: false,
      status: 500,
      json: async () => ({ error: 'backend refused to start' }),
    })
    assert.equal(requests.length, 1)
    const replacement = updates.find((update) => update.index === 1 && typeof update.next === 'function')
    assert.equal(replacement, undefined, 'row keeps its previous state')
    const failure = updates.find((update) => update.index === 5 && update.next !== null)
    assert.ok(failure, 'failure state update')
    assert.equal(failure.next.id, 'py-hello')
    assert.equal(failure.next.message, 'backend refused to start')
  })
}

try {
  await main()
} catch (error) {
  failures.push('unexpected failure outside a check')
  console.error(error)
}

section('Summary')
console.log(`  ${passed} check(s) passed, ${failures.length} failed`)
for (const failure of failures) console.log(`  failed: ${failure}`)
if (failures.length > 0) process.exitCode = 1
